1	export type Customer = {
2	  yearsWithMHPCO: number;
3	  previousContracts: number;
4	};
5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const CURSED_SURCHARGE_RATE = 0.5;
25	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
26	const HIGH_ENCHANTMENT_THRESHOLD = 5;
27	
28	const basePremiumOf = (item: Item): number =>
29	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
30	
31	const itemModifierRateOf = (item: Item): number =>
32	  (item.cursed ? CURSED_SURCHARGE_RATE : 0) +
33	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
34	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
35	    : 0);
36	
37	const premiumOf = (item: Item): number =>
38	  basePremiumOf(item) * (1 + itemModifierRateOf(item));
39	
40	const sumItemPremiums = (items: Item[]): number =>
41	  items.reduce((sum, item) => sum + premiumOf(item), 0);
42	
43	// Policy-level modifiers are whole percentages of the policy base premium.
44	// Applying them as `amount * percent / 100` keeps the arithmetic exact:
45	// `100 * 110 / 100` is 110, whereas `100 * 1.1` is 110.00000000000001.
46	const applyPercentage = (amount: number, percent: number): number =>
47	  (amount * percent) / 100;
48	
49	const FULL_PERCENTAGE = 100;
50	const FIRST_INSURANCE_SURCHARGE_PERCENTAGE = 10;
51	const LOYALTY_DISCOUNT_PERCENTAGE = 20;
52	const LOYALTY_YEARS_THRESHOLD = 2;
53	
54	const loyaltyDiscountPercentageOf = (customer: Customer): number =>
55	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
56	    ? LOYALTY_DISCOUNT_PERCENTAGE
57	    : 0;
58	
59	const policyPercentageOf = (customer: Customer): number =>
60	  FULL_PERCENTAGE +
61	  FIRST_INSURANCE_SURCHARGE_PERCENTAGE -
62	  loyaltyDiscountPercentageOf(customer);
63	
64	const BLOCK_SIZE = 3;
65	const BLOCK_BASE_PREMIUM = 60;
66	
67	const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
68	  sameTypeGroup.length === BLOCK_SIZE;
69	
70	const groupByType = (items: Item[]): Item[][] => {
71	  const groups = new Map<string, Item[]>();
72	  for (const item of items) {
73	    const group = groups.get(item.type) ?? [];
74	    group.push(item);
75	    groups.set(item.type, group);
76	  }
77	  return [...groups.values()];
78	};
79	
80	const premiumOfGroup = (sameTypeGroup: Item[]): number =>
81	  isComponentBlock(sameTypeGroup)
82	    ? BLOCK_BASE_PREMIUM
83	    : sumItemPremiums(sameTypeGroup);
84	
85	export const quote = (customer: Customer, items: Item[]): number => {
86	  const policyPremium = groupByType(items).reduce(
87	    (sum, group) => sum + premiumOfGroup(group),
88	    0,
89	  );
90	
91	  const withPolicyModifiers = applyPercentage(
92	    policyPremium,
93	    policyPercentageOf(customer),
94	  );
95	
96	  return withPolicyModifiers + PROCESSING_FEE;
97	};
98	
99	export const claim = (): number => {
100	  return undefined as unknown as number;
101	};
